{"cards": [{"node_code": "N_beed099ee472ed8b", "definition": "研究利用锤击、压力机或旋锻等设备，通过自由锻或模具约束使金属坯料产生塑性变形，从而获得锻件的工艺、装备及质量控制技术。", "boundary": "聚焦于离散或半连续的锻造过程，包括自由锻、模锻、胎模锻及特种锻造（如环锻、旋锻）。边界在于强调“打击”或“局部加压”的成形方式，区别于连续流动的轧制、挤压及拉拔工艺。涵盖锻件设计、模具结构、成形工艺参数及锻后热处理。", "includes": ["自由锻、模锻、胎模锻等常规锻造工艺及装备", "环锻、旋锻、等温锻造等特种锻造技术", "锻件工艺设计、模具结构分析及成形缺陷控制"], "excludes": ["金属在轧辊间连续通过的轧制工艺", "金属在挤压筒内受压通过模孔的挤压工艺"], "sibling_distinctions": [{"other_code": "N_777b6f0536105385", "rule": "本节点关注离散或半连续的打击/局部加压成形（如锻锤、压力机），兄弟节点关注连续流动的挤压/拉伸成形（如轧机、挤压机）。"}, {"other_code": "N_34da5688badbf806", "rule": "本节点关注具体的锻造工艺过程与装备，兄弟节点关注通用的成形力学分析、模具通用设计及缺陷机理。"}], "cross_boundary_rule": "若研究重点为锻造过程中的力学行为或模具通用设计理论，可关联“成形载荷、模具与缺陷控制”；若为具体锻造工艺或装备，主挂载本节点。"}, {"node_code": "N_777b6f0536105385", "definition": "研究利用轧辊、挤压筒或拉拔模等工具，使金属坯料在连续或半连续状态下产生塑性变形，从而获得型材、板材、管材或线材的工艺、装备及理论。", "boundary": "聚焦于连续或半连续的体积塑性成形过程，包括热轧、冷轧、挤压、拉拔及连铸连轧等。边界在于强调“连续流动”或“长材/板材”的成形特征，区别于离散打击的锻造工艺。涵盖变形机理、工艺参数优化及表面质量控制。", "includes": ["热轧、冷轧、连轧等板材与型材轧制工艺", "热挤压、冷挤压等挤压成形工艺及模具", "拉拔、连拉等线材及管材成形工艺"], "excludes": ["利用锤击或压力机进行离散打击的锻造工艺", "薄板或管材的弯曲、拉深等板料成形工艺"], "sibling_distinctions": [{"other_code": "N_beed099ee472ed8b", "rule": "本节点关注连续流动的挤压/拉伸成形（如轧机、挤压机），兄弟节点关注离散或半连续的打击/局部加压成形（如锻锤、压力机）。"}, {"other_code": "N_34da5688badbf806", "rule": "本节点关注具体的轧制、挤压、拉拔工艺过程与装备，兄弟节点关注通用的成形力学分析、模具通用设计及缺陷机理。"}], "cross_boundary_rule": "若研究重点为轧制/挤压过程中的力学行为或模具通用设计理论，可关联“成形载荷、模具与缺陷控制”；若为具体工艺或装备，主挂载本节点。"}, {"node_code": "N_34da5688badbf806", "definition": "研究体积塑性成形过程中的力学行为、载荷计算、模具结构设计及成形缺陷形成机理与控制方法的基础理论与通用技术。", "boundary": "聚焦于跨工艺（锻造、轧制、挤压等）的通用成形理论、模具设计原则及缺陷控制策略。边界在于强调“通用性”与“理论/设计”，不特指某一种具体成形工艺（如仅锻造或仅轧制）。涵盖有限元模拟、模具材料选择、润滑技术及缺陷检测与预防。", "includes": ["塑性成形过程的力学分析、有限元模拟及载荷计算", "通用模具结构设计、材料选择及寿命分析", "成形缺陷（如折叠、裂纹、缩孔）的形成机理与控制方法"], "excludes": ["特定锻造工艺（如模锻）的具体操作与装备", "特定轧制或挤压工艺的具体参数优化"], "sibling_distinctions": [{"other_code": "N_beed099ee472ed8b", "rule": "本节点关注通用的成形力学、模具设计及缺陷理论，兄弟节点关注具体的锻造工艺过程与装备。"}, {"other_code": "N_777b6f0536105385", "rule": "本节点关注通用的成形力学、模具设计及缺陷理论，兄弟节点关注具体的轧制、挤压、拉拔工艺过程与装备。"}], "cross_boundary_rule": "若研究为特定工艺（如锻造）的专用模具或工艺参数，主挂载相应工艺节点；若为跨工艺的通用理论、模拟方法或通用模具设计，主挂载本节点。"}]}
